artifact-container.css:
/* Main Container */
.artifact-container {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background: var(--dark-900);
}

artifact-header.css:
/* Header */
.artifact-header {
    height: 70px;
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--glass-border);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 24px;
    box-shadow: var(--glass-shadow);
    position: relative;
    z-index: 1000;
}

artifact-icon.css:
.artifact-icon {
    width: 48px;
    height: 48px;
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 20px;
}

artifact-info.css:
.artifact-info h1 {
    font-size: 18px;
    font-weight: 600;
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

execution-status.css:
.execution-status {
    display: flex;
    align-items: center;
    gap: 8px;
    background: var(--dark-700);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    padding: 8px 16px;
    font-size: 12px;
}

status-indicator.css:
.status-indicator {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-green);
    animation: pulse 2s infinite;
}

header-btn.css:
.header-btn {
    width: 40px;
    height: 40px;
    border: none;
    background: var(--dark-700);
    color: var(--light-300);
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
}



.header-btn:hover {
    background: var(--dark-600);
    color: var(--accent-blue);
    transform: translateY(-2px);
}



.header-btn.active {
    background: var(--accent-blue);
    color: white;
}

active.css:
.header-btn.active {
    background: var(--accent-blue);
    color: white;
}



.file-item.active {
    background: var(--accent-blue);
    color: white;
}



.editor-tab.active {
    background: var(--dark-800);
    color: var(--accent-blue);
}



.panel-tab.active {
    color: var(--accent-blue);
    background: var(--dark-700);
}

unlimited-badge.css:
.unlimited-badge {
    background: linear-gradient(135deg, var(--accent-yellow), var(--accent-red));
    color: white;
    padding: 6px 12px;
    border-radius: 16px;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

artifact-main.css:
/* Main Content Area */
.artifact-main {
    flex: 1;
    display: flex;
    overflow: hidden;
}

artifact-sidebar.css:
/* Left Sidebar - Navigation & Controls */
.artifact-sidebar {
    width: 320px;
    background: var(--dark-800);
    border-right: 1px solid var(--glass-border);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}


    .artifact-sidebar {
        width: 280px;
    }

section-header.css:
.section-header {
    padding: 16px 20px;
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--glass-border);
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--light-400);
}

execution-env.css:
/* Execution Environment Panel */
.execution-env {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

env-dropdown.css:
.env-dropdown {
    width: 100%;
    background: var(--dark-600);
    border: 1px solid var(--glass-border);
    border-radius: 8px;
    padding: 12px;
    color: var(--light-100);
    font-size: 14px;
    cursor: pointer;
    transition: all 0.3s ease;
}



.env-dropdown:hover {
    border-color: var(--accent-blue);
}

env-icon.css:
.env-icon {
    width: 20px;
    height: 20px;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
}

quick-actions.css:
/* Quick Actions Grid */
.quick-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-top: 16px;
}

quick-action.css:
/* Quick Actions Grid */
.quick-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-top: 16px;
}



.quick-action {
    background: var(--dark-600);
    border: 1px solid var(--glass-border);
    border-radius: 8px;
    padding: 12px;
    cursor: pointer;
    transition: all 0.3s ease;
    text-align: center;
    font-size: 12px;
}



.quick-action:hover {
    background: var(--dark-500);
    border-color: var(--accent-blue);
    transform: translateY(-2px);
}



.quick-action i {
    display: block;
    font-size: 16px;
    margin-bottom: 4px;
    color: var(--accent-blue);
}

file-explorer.css:
/* File Explorer */
.file-explorer {
    flex: 1;
    display: flex;
    flex-direction: column;
}

file-item.css:
.file-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 13px;
}



.file-item:hover {
    background: var(--dark-600);
}



.file-item.active {
    background: var(--accent-blue);
    color: white;
}

file-icon.css:
.file-icon {
    width: 16px;
    height: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
}

artifact-editor.css:
/* Center - Editor Area */
.artifact-editor {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

editor-tabs.css:
.editor-tabs {
    height: 40px;
    background: var(--dark-700);
    border-bottom: 1px solid var(--glass-border);
    display: flex;
    align-items: center;
    padding: 0 12px;
    overflow-x: auto;
}

editor-tab.css:
.editor-tabs {
    height: 40px;
    background: var(--dark-700);
    border-bottom: 1px solid var(--glass-border);
    display: flex;
    align-items: center;
    padding: 0 12px;
    overflow-x: auto;
}



.editor-tab {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    background: var(--dark-600);
    border-radius: 6px 6px 0 0;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 12px;
    white-space: nowrap;
    margin-right: 4px;
}



.editor-tab.active {
    background: var(--dark-800);
    color: var(--accent-blue);
}

tab-close.css:
.tab-close {
    width: 16px;
    height: 16px;
    border-radius: 2px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
    opacity: 0.6;
    transition: all 0.2s ease;
}



.tab-close:hover {
    opacity: 1;
    background: var(--accent-red);
    color: white;
}

execution-terminal.css:
/* Execution Terminal */
.execution-terminal {
    height: 300px;
    background: var(--dark-950);
    border-top: 1px solid var(--glass-border);
    display: flex;
    flex-direction: column;
    font-family: 'Consolas', 'Monaco', monospace;
    resize: vertical;
    overflow: hidden;
}

terminal-header.css:
.terminal-header {
    height: 32px;
    background: var(--dark-800);
    border-bottom: 1px solid var(--glass-border);
    display: flex;
    align-items: center;
    padding: 0 12px;
    justify-content: space-between;
}

terminal-title.css:
.terminal-title {
    font-size: 11px;
    color: var(--light-400);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

terminal-btn.css:
.terminal-btn {
    width: 20px;
    height: 20px;
    border: none;
    border-radius: 3px;
    cursor: pointer;
    font-size: 10px;
    transition: all 0.2s ease;
}



.terminal-btn.clear { background: var(--accent-red); color: white; }


.terminal-btn.expand { background: var(--accent-blue); color: white; }

terminal-content.css:
.terminal-content {
    flex: 1;
    padding: 12px;
    overflow-y: auto;
    font-size: 13px;
    line-height: 1.4;
}

artifact-right-panel.css:
/* Right Panel - Advanced Features */
.artifact-right-panel {
    width: 400px;
    background: var(--dark-800);
    border-left: 1px solid var(--glass-border);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}


    .artifact-right-panel {
        width: 350px;
    }



    .artifact-right-panel {
        width: 320px;
    }

panel-tabs.css:
.panel-tabs {
    height: 48px;
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--glass-border);
    display: flex;
    align-items: center;
}

panel-tab.css:
.panel-tabs {
    height: 48px;
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--glass-border);
    display: flex;
    align-items: center;
}



.panel-tab {
    flex: 1;
    height: 100%;
    border: none;
    background: transparent;
    color: var(--light-400);
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
}



.panel-tab.active {
    color: var(--accent-blue);
    background: var(--dark-700);
}

metric-card.css:
.metric-card {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 16px;
    text-align: center;
}

metric-label.css:
.metric-label {
    font-size: 11px;
    color: var(--light-400);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

performance-chart.css:
.performance-chart {
    height: 200px;
    background: var(--dark-700);
    border-radius: 8px;
    margin-bottom: 20px;
    position: relative;
}

video-controls.css:
.video-controls {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}

video-input.css:
.video-input {
    width: 100%;
    background: var(--dark-600);
    border: 1px solid var(--glass-border);
    border-radius: 8px;
    padding: 12px;
    color: var(--light-100);
    font-size: 14px;
    margin-bottom: 12px;
}



.video-input::placeholder {
    color: var(--light-400);
}

video-btn.css:
.video-btn {
    flex: 1;
    padding: 12px;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 600;
    transition: all 0.3s ease;
}



.video-btn.download {
    background: linear-gradient(135deg, var(--accent-red), var(--accent-yellow));
    color: white;
}



.video-btn.process {
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    color: white;
}



.video-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

download.css:
.video-btn.download {
    background: linear-gradient(135deg, var(--accent-red), var(--accent-yellow));
    color: white;
}

process.css:
.video-btn.process {
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    color: white;
}

video-preview.css:
.video-preview {
    width: 100%;
    height: 200px;
    background: var(--dark-700);
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--light-400);
    font-size: 12px;
    margin-top: 16px;
}

training-status.css:
.training-status {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}

training-progress.css:
.training-progress {
    width: 100%;
    height: 8px;
    background: var(--dark-600);
    border-radius: 4px;
    overflow: hidden;
    margin-bottom: 12px;
}

progress-bar.css:
.progress-bar {
    height: 100%;
    background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));
    width: 0%;
    transition: width 1s ease;
}

training-stat.css:
.training-status {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}



.training-stats {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-top: 12px;
}



.training-stat {
    display: flex;
    justify-content: space-between;
    font-size: 12px;
}

research-controls.css:
.research-controls {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}

research-input.css:
.research-input {
    width: 100%;
    background: var(--dark-600);
    border: 1px solid var(--glass-border);
    border-radius: 8px;
    padding: 12px;
    color: var(--light-100);
    font-size: 14px;
    margin-bottom: 12px;
}

research-btn.css:
.research-btn {
    width: 100%;
    padding: 12px;
    border: none;
    border-radius: 8px;
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue));
    color: white;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
}



.research-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(6, 182, 212, 0.3);
}

screenshot-item.css:
.screenshot-item {
    aspect-ratio: 16/9;
    background: var(--dark-700);
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: all 0.3s ease;
}



.screenshot-item:hover {
    transform: scale(1.02);
}

git-controls.css:
.git-controls {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}

git-input.css:
.git-input {
    width: 100%;
    background: var(--dark-600);
    border: 1px solid var(--glass-border);
    border-radius: 8px;
    padding: 12px;
    color: var(--light-100);
    font-size: 14px;
    margin-bottom: 12px;
}

git-btn.css:
.git-btn {
    width: 100%;
    padding: 12px;
    border: none;
    border-radius: 8px;
    background: linear-gradient(135deg, var(--accent-purple), var(--accent-blue));
    color: white;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
}



.git-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 16px rgba(139, 92, 246, 0.3);
}

repo-browser.css:
.repo-browser {
    max-height: 300px;
    overflow-y: auto;
    background: var(--dark-700);
    border-radius: 8px;
    margin-top: 16px;
}

repo-item.css:
.repo-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 12px;
    border-bottom: 1px solid var(--dark-600);
}



.repo-item:hover {
    background: var(--dark-600);
}

loading.css:
/* Loading States */
.loading {
    display: inline-block;
    width: 16px;
    height: 16px;
    border: 2px solid var(--dark-600);
    border-radius: 50%;
    border-top-color: var(--accent-blue);
    animation: spin 1s ease-in-out infinite;
}
